css:
.omd [data-omd-part="conversation"], .omd [data-omd-part="header"] {
  background: var(--omd-bg); color: var(--omd-text);
}
.omd [data-omd-part="sidebar"] {
  background: var(--omd-sidebar); backdrop-filter: blur(24px); border: 0;
}
.omd [data-omd-part="composer"] {
  background: var(--omd-composer); border: 1px solid var(--omd-border);
  border-radius: 26px; box-shadow: var(--omd-shadow);
}
.omd [data-omd-part="composer"]:focus-within {
  border-color: color-mix(in srgb, var(--omd-text) 22%, var(--omd-border));
  box-shadow: 0 2px 10px #0000000a;
}
.omd [data-omd-part="message-user"] {
  background: var(--omd-user-bg); color: var(--omd-user-text); border: 0; border-radius: 17px;
}
.omd [data-omd-part="form-control"] {
  background: var(--omd-surface); color: var(--omd-text); border: 1px solid var(--omd-border); border-radius: 8px; box-shadow: none;
}
.omd [data-omd-part="button-primary"], .omd [data-omd-part="send"] {
  background: var(--omd-button-bg); color: var(--omd-button-fg); border: 0; border-radius: 999px; box-shadow: none;
}
.omd [data-omd-part="send"]:disabled {
  background: var(--omd-send-idle); color: var(--omd-button-fg);
}
.omd [data-omd-part="button"]:focus-visible,
.omd [data-omd-part="form-control"]:focus-visible {
  outline: 2px solid var(--omd-focus); outline-offset: 2px;
}
.omd [data-omd-part="dialog"], .omd [data-omd-part="menu"] {
  color: var(--omd-text); background: var(--omd-surface-solid); border: 1px solid var(--omd-border); border-radius: 14px; box-shadow: 0 12px 40px #00000020;
}
.omd [data-omd-part="settings-nav-item"][data-omd-state="selected"] {
  background: var(--omd-selected); color: var(--omd-text); font-weight: 500;
}
.omd [data-omd-part="process-toggle"] { color: var(--omd-muted); background: transparent; border: 0; }
.omd [data-omd-part="tool-group"] { border-color: var(--omd-border); background: transparent; }
.omd [data-omd-part="code-block"] { background: var(--omd-subtle); border: 1px solid var(--omd-border); border-radius: 10px; }
.omd [data-omd-part="code-inline"] { background: var(--omd-code-bg); border-radius: 4px; }
.omd [data-omd-part="workbench"] { background: var(--omd-bg); color: var(--omd-text); border-radius: 0; box-shadow: none; }
.omd [data-omd-part="settings-content"] { background: var(--omd-bg); }
